import hashlib
import runpy
import tempfile

root = Path.cwd()
protected = [root / name for name in ('ledger.py', 'test_ledger.py', 'test_public.py', 'CONTRACT.md', 'AGENTS.md')]
protected += [p for directory in ('.baseline', '.agents') for p in (root / directory).rglob('*') if p.is_file()]
