probe = r'''
from copy import deepcopy
from itertools import product
from collections import Counter
import random
from ledger import Ledger

counts = Counter()

class Reference:
    def __init__(self, balances):
        self.balances = dict(balances)
        self.history = {}

    def transfer(self, source, target, amount, key):
        if not isinstance(source, str) or not isinstance(target, str):
            raise ValueError
        if source == target or source not in self.balances or target not in self.balances:
            raise ValueError
        if not isinstance(amount, int) or isinstance(amount, bool) or amount <= 0:
            raise ValueError
        if not isinstance(key, str) or key == '':
            raise ValueError
        payload = {'source': source, 'target': target, 'amount': amount, 'key': key}
        if key in self.history:
            if payload != self.history[key]:
                raise ValueError
        else:
            if amount > self.balances[source]:
                raise ValueError
            self.balances = {account: balance + (amount if account == target else -amount if account == source else 0)
                             for account, balance in self.balances.items()}
            self.history[key] = dict(payload)
        return payload

    def batch(self, operations):
        previous = deepcopy((self.balances, self.history))
        try:
            if not isinstance(operations, list):
                raise ValueError
            receipts = []
            for op in operations:
                if not isinstance(op, dict) or set(op) != {'source', 'target', 'amount', 'key'}:
                    raise ValueError
                receipts.append(self.transfer(**op))
            return receipts
        except Exception:
            self.balances, self.history = previous
            raise


def check(ledger, reference, method, argument, label):
    old = deepcopy((ledger.balances, ledger.history))
    input_before = deepcopy(argument)
    balances_ref, history_ref = ledger.balances, ledger.history
    prior_receipts = dict(ledger.history)
    def invoke(obj):
        try:
            result = getattr(obj, method)(**argument) if method == 'transfer' else obj.batch(argument)
            return 'ok', result
        except Exception as exc:
            return type(exc).__name__, None
    expected = invoke(reference)
    observed = invoke(ledger)
    assert observed == expected, (label, method, argument, expected, observed)
    assert (ledger.balances, ledger.history) == (reference.balances, reference.history), (label, argument)
    assert ledger.balances is balances_ref and ledger.history is history_ref, label
    assert argument == input_before, (label, 'caller input changed')
    assert all(ledger.history[key] is receipt for key, receipt in prior_receipts.items()), label
    assert sum(ledger.balances.values()) == sum(old[0].values()), (label, 'money conservation')
    assert all(type(value) is int and value >= 0 for value in ledger.balances.values()), label
    if observed[0] != 'ok':
        assert observed[0] == 'ValueError', (label, observed)
        assert (ledger.balances, ledger.history) == old, (label, 'failure changed state')
        counts['rejected_' + method] += 1
    else:
        saved = deepcopy((ledger.balances, ledger.history))
        receipts = observed[1] if method == 'batch' else [observed[1]]
        assert len({id(receipt) for receipt in receipts}) == len(receipts), (label, 'shared returned receipts')
        for receipt in receipts:
            assert all(receipt is not stored for stored in ledger.history.values()), label
            receipt.clear()
            receipt['caller-change'] = []
        assert (ledger.balances, ledger.history) == saved, (label, 'receipt alias')
        counts['successful_' + method] += 1

# All tiny balances, source/target choices, and boundary amounts/keys.
for balance_a, balance_b in product(range(4), repeat=2):
    for source, target, amount, key in product(('a', 'b', 'missing'), ('a', 'b', 'missing'), (-1, 0, 1, 2, 4, True, 1.0, None), ('', 'one')):
        start = {'a': balance_a, 'b': balance_b}
        check(Ledger(start), Reference(start), 'transfer', dict(source=source, target=target, amount=amount, key=key), 'tiny-transfer')

# Exhaust all pairs, including duplicate keys, invalid shape and dependent spending.
ops = [
    dict(source='a', target='b', amount=1, key='one'),
    dict(source='a', target='b', amount=2, key='one'),
    dict(source='b', target='a', amount=1, key='two'),
    dict(source='b', target='c', amount=1, key='three'),
    dict(source='c', target='a', amount=1, key='four'),
    dict(source='a', target='missing', amount=1, key='bad'),
    dict(source='a', target='a', amount=1, key='bad'),
    dict(source='a', target='b', amount=False, key='bad'),
    dict(source='a', target='b', amount=1, key=[]),
    {}, None,
]
for start in ({'a': 2, 'b': 0, 'c': 0}, {'a': 0, 'b': 1, 'c': 2}):
    for first, second in product(ops, repeat=2):
        check(Ledger(start), Reference(start), 'batch', [first, second], 'batch-pair')

# Seeded, stateful sequences interleave success, replay, conflict, invalid types,
# batch failures and retries through the public API.
rng = random.Random(92341)
accounts = ('a', 'b', 'c', '', '雪\x00')
for scenario in range(60):
    start = {name: rng.randrange(30) for name in accounts}
    ledger, reference = Ledger(start), Reference(start)
    for step in range(80):
        def next_operation():
            if reference.history and rng.random() < 0.4:
                result = dict(rng.choice(list(reference.history.values())))
                if rng.random() < 0.35:
                    result['amount'] += 1
                return result
            source, target = rng.sample(accounts, 2)
            result = dict(source=source, target=target, amount=rng.randrange(1, 20), key='key-' + str(rng.randrange(40)))
            if rng.random() < 0.25:
                field = rng.choice(('source', 'target', 'amount', 'key'))
                choices = {'source': ['missing', [], None, 3], 'target': ['missing', {}, None, 3], 'amount': [0, -1, True, False, 1.0, [], None, '1'], 'key': ['', 2, False, [], None]}
                result[field] = rng.choice(choices[field])
            return result
        if rng.random() < 0.5:
            check(ledger, reference, 'transfer', next_operation(), ('random', scenario, step))
        else:
            operations = [next_operation() for _ in range(rng.randrange(6))]
            if rng.random() < 0.1:
                operations.append(rng.choice((None, {}, {'extra': 1})))
            check(ledger, reference, 'batch', operations, ('random', scenario, step))

# Constructor boundaries, alias isolation and input preservation.
for initial in ({}, {'a': 0}, {'a': 10**400, '': 0, '\x00': 1}):
    ledger = Ledger(initial)
    original = dict(initial)
    assert ledger.balances == initial and ledger.balances is not initial
    initial['outside'] = 1
    assert ledger.balances == original and ledger.history == {}
    counts['valid_constructors'] += 1
for invalid in (-1, True, False, 1.0, float('nan'), float('inf'), 1j, '1', None, [], {}, set()):
    initial = {'a': 10, 'b': invalid}
    value_refs = dict(initial)
    try:
        Ledger(initial)
    except ValueError:
        pass
    else:
        raise AssertionError(('constructor accepted', invalid))
    assert initial.keys() == value_refs.keys() and all(initial[key] is value for key, value in value_refs.items())
    counts['invalid_constructors'] += 1
for invalid in (None, [], (), 'a', 1, {1: 10}, {None: 1}):
    try:
        Ledger(invalid)
    except ValueError:
        counts['invalid_constructors'] += 1
    else:
        raise AssertionError(('constructor accepted', invalid))

# A complete multi-transfer journey, rollback, recovery, depleted-source replay,
# unusual valid strings and arbitrary-precision integers.
start = {'vault': 10**400, '': 0, '雪\x00': 0}
ledger, reference = Ledger(start), Reference(start)
fund = dict(source='vault', target='', amount=10**400, key=' ')
pay = dict(source='', target='雪\x00', amount=7, key='\x00')
check(ledger, reference, 'transfer', fund, 'journey-funding')
check(ledger, reference, 'batch', [fund, pay, pay], 'journey-payment-and-replay')
refund = dict(source='雪\x00', target='', amount=3, key='refund')
check(ledger, reference, 'batch', [refund, dict(source='vault', target='', amount=1, key='retry')], 'journey-rollback')
check(ledger, reference, 'batch', [refund, dict(source='', target='vault', amount=2, key='retry')], 'journey-recovery')
check(ledger, reference, 'batch', [fund, pay, refund], 'journey-replay')
assert ledger.balances == {'vault': 2, '': 10**400 - 6, '雪\x00': 4}
assert len(ledger.history) == 4
print('Independent public-API probes passed:', dict(sorted(counts.items())))
print('Random seed: 92341; 60 stateful scenarios x 80 actions; no candidate or test files changed.')
'''
with tempfile.TemporaryDirectory(prefix='.assessment-probe-', dir=root) as directory:
    script = Path(directory) / 'probe.py'
    script.write_text(probe)
    runpy.run_path(str(script), run_name='__main__')
after = {str(p.relative_to(root)): hashlib.sha256(p.read_bytes()).hexdigest() for p in protected}
assert before == after, 'Read-only assessment changed protected files'
print('Application, tests, instructions, baseline, and skill hashes unchanged across probes.')
